import{_ as e,o as a,c as l,ao as r}from"./chunks/framework.AQkxRU0n.js";const m=JSON.parse('{"title":"Colmat.jl マニュアル","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),d={name:"index.md"};function o(n,t,s,i,c,f){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="Colmat.jl-マニュアル" tabindex="-1">Colmat.jl マニュアル <a class="header-anchor" href="#Colmat.jl-マニュアル" aria-label="Permalink to &quot;Colmat.jl マニュアル {#Colmat.jl-マニュアル}&quot;">​</a></h1><p>Colmat.jl は Rust の <a href="https://github.com/tensor4all/faer" target="_blank" rel="noreferrer">colmat</a> を Julia から呼び出す線形代数パッケージです。 <code>FaerMatrix</code> などの Rust 所有配列を Julia の <code>AbstractArray</code> として扱い、 <code>LinearAlgebra</code> の分解・求解や疎行列・反復法を利用できます。</p><p>初めて使う場合は <a href="./installation">インストール</a> の後、 <a href="./manual/arrays">配列・型・所有権</a> と <a href="./manual/dense">密行列の分解と求解</a> を読んでください。</p><table tabindex="0"><thead><tr><th style="text-align:left;">目的</th><th style="text-align:left;">ページ</th></tr></thead><tbody><tr><td style="text-align:left;">配列の構築・変換、ビューと寿命を理解する</td><td style="text-align:left;"><a href="./manual/arrays">配列・型・所有権</a></td></tr><tr><td style="text-align:left;">分解を保存して繰り返し解く</td><td style="text-align:left;"><a href="./manual/dense">密行列の分解と求解</a></td></tr><tr><td style="text-align:left;">固有値・左右固有ベクトル、Schur・QZ を計算する</td><td style="text-align:left;"><a href="./manual/spectral">固有値・Schur・QZ</a></td></tr><tr><td style="text-align:left;">CSC/CSR、ordering、symbolic analysis を使う</td><td style="text-align:left;"><a href="./manual/sparse">疎行列と直接法</a></td></tr><tr><td style="text-align:left;">疎な最小二乗・最小ノルム問題を解く</td><td style="text-align:left;"><a href="./manual/sparse-qr">疎 QR</a></td></tr><tr><td style="text-align:left;">作用素や前処理を使って反復法で解く</td><td style="text-align:left;"><a href="./manual/operators">線形作用素・反復法</a></td></tr><tr><td style="text-align:left;">Householder・Jacobi・帯行列への縮約を使う</td><td style="text-align:left;"><a href="./manual/reductions">反射・回転・縮約</a></td></tr><tr><td style="text-align:left;">scratch とスレッドチームを再利用する</td><td style="text-align:left;"><a href="./manual/resources">作業領域とチーム</a></td></tr><tr><td style="text-align:left;">統計・乱数・NPY を使う</td><td style="text-align:left;"><a href="./manual/utilities">統計・乱数・NPY</a></td></tr></tbody></table><h2 id="共通の規約" tabindex="-1">共通の規約 <a class="header-anchor" href="#共通の規約" aria-label="Permalink to &quot;共通の規約 {#共通の規約}&quot;">​</a></h2><p>密配列のネイティブ数値型は <code>Float32</code>・<code>Float64</code>・<code>ComplexF32</code>・<code>ComplexF64</code> です。 添字と置換は Julia と同じ 1-based です。構築・明示変換は通常コピーを作り、 ビューは元の所有者を保持します。<code>!</code> 付き操作のストレージ共有や失敗時の挙動は各節で説明します。</p><p><code>scratch=</code> はカーネルの一時領域を制御します。返り値・型変換・更新の staging などは 別途メモリを確保するため、呼び出し全体が allocation-free になるとは限りません。 <code>team=</code> を受け取る場合も、カーネルによっては逐次実行になります。</p><p>このマニュアルは README の利用例を分野別に整理したものです。 API を探す場合は <a href="./reference/api">API 案内</a>、開発やビルドは <a href="./development">開発ガイド</a> を参照してください。 実装の履歴・未完了項目は <a href="https://github.com/AtelierArith/Colmat.jl/blob/main/docs/implementation-status.md" target="_blank" rel="noreferrer">実装台帳</a> に記録しています。</p>',8)])])}const u=e(d,[["render",o]]);export{m as __pageData,u as default};
